type Effectivity struct {
	From  time.Time   // date at 00:00:00 UTC
	Until *time.Time  // nil = until further notice
}

func (e Effectivity) EffectiveOn(asOf time.Time) bool {
	return !asOf.Before(e.From) && (e.Until == nil || asOf.Before(*e.Until))
}

