import "github.com/rickb777/date/v2"

type Effectivity struct{ From, Until date.Date }   // Until == 0 (year 0) => open

func (e Effectivity) EffectiveOn(asOf date.Date) bool {
	return e.From <= asOf && (e.Until == 0 || asOf < e.Until)
}
